def compute(vars):
    costs_millions = vars["v1"]
    note_principal_millions = vars["v2"] * 1000

    if note_principal_millions == 0:
        return None

    ratio_percent = (costs_millions / note_principal_millions) * 100

    return {
        "value": ratio_percent,
        "trace": {
            "costs_millions": costs_millions,
            "note_principal_millions": note_principal_millions,
            "ratio_percent": ratio_percent,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
